            font-size: 9pt;
        }

        .item {
            margin-bottom: 10px;
        }

        .item span:first-child {
            font-weight: bold;
        }

        .price {
            float: right;
        }

        p {
            padding: 0;
            margin: 0;
            font-weight: 300;
            font-size: 9pt;
            width: 70%;
        }

        .page {
            width: 210mm;
            height: 297mm;
            margin: 0 auto;
            box-sizing: border-box;
            page-break-after: initial;
            position: relative;
            overflow: hidden;
            background-color: rgb(210, 200, 180);
            font-family: Jungka, serif;
            padding-left: 20mm;
            padding-right: 20mm;
            padding-top: 10mm;
        }

        .page .footer {
            position: absolute;
            bottom: 0;
            padding-left: 20mm;
            padding-right: 20mm;
            left: 0;
            right: 0;
            z-index: 10;
            font-size: 9pt;
            font-weight: 300;
            overflow: hidden;
            height: 100%;
        }

