            width: 100px:
        }

        .page .footer .right {
            width: 50%;
            float: right;
        }

        .page .footer .right .origin {
            font-weight: 500;
        }

        .page .footer .badge {
            position: absolute;
            bottom: 30px;
            height: 51mm;
            z-index: 10;
            left: 0;
            right: 0;
        }

        .page .footer .illustration {
        }

        .columns {
            position: absolute;
            width: 630px;
            bottom: 20mm;
            display: grid;
            grid-template-columns: 1fr 1fr;
            justify-content: left;
            z-index: 10;
        }

        .columns h4 {
            margin-bottom: 5px;
            margin-top: 0;
        }

        .columns .origin {
            display: grid;
            grid-template-columns: 1fr 1fr;
            margin-top: 3px;
        }

        #overlay {
            position: absolute;
            right: 80px;
            top: 40px;
            height: 24mm;
            width: 32mm;
